```python
import re

def извлекать поля(text):
    поля = {
        'название': None,
        'бренд': None,
        'цвет': None,
        'ёмкость_аккумулятора_мАч': None,
        'вес_г': None,
        'гарантия_мес': None
    }

    # Поиск ключевых слов
    key_words = ['название', 'бренд', 'цвет', 'ёмкость_аккумулятора_мАч', 'вес_г', 'гарантия_мес']
    for key in key_words:
        if re.search(key, text, re.IGNORECASE):
            if key == 'ёмкость_аккумулятора_мАч':
                поля[key] = text.split('мАч')[1].split(' ')[0]
            elif key == 'вес_г':
                поля[key] = text.split('г')[1].split(' ')[0]
            elif key == 'гарантия_мес':
                поля[key] = text.split('мес')[1].split(' ')[0]
            else:
                поля[key] = text.split(key)[1].split(' ')[0]

    return поля

